base.src/validate.ts:
export function validate(value: string | undefined): asserts value is string {
  if (value === undefined) throw new Error("missing");
}

files.src/name.ts:
import { validate } from "./validate";
export function name(input: { name?: string }) {
  validate(input.name);
  return input.name!.trim();
}

files.src/email.ts:
import { validate } from "./validate";
export function email(input: { email?: string }) {
  validate(input.email);
  return input.email!.toLowerCase();
}

files.src/phone.ts:
import { validate } from "./validate";
export function phone(input: { phone?: string }) {
  validate(input.phone);
  return input.phone!.replace(/ /g, "");
}
